import * as React from "react";
import { Segment, Container, Header, Image } from "semantic-ui-react";
import { withLayout } from "../../components/Layout";
import { withPrefix } from "gatsby";

const ProfilingPage = () => {
  return (

    <Container text>

      <Segment>
        This page lists some notes that I have on profiling. I do it infrequently enough that I always forget the name of certain tools (speedscope!).
      </Segment>

      <Header as="h3">A Good Profiler Visualization Tool</Header>

      I really like <a href="https://www.speedscope.app/">speedscope</a> for visualizing profiling data. It's a browser based tool that lets you select a local profile file, and then displays it. Even though you can load
      the webpage from a local file, it doesn't actually upload your profile data; it's all processed locally in your browser.

      <Image src="https://user-images.githubusercontent.com/150329/40900669-86eced80-6781-11e8-92c1-dc667b651e72.gif" />

      <Header as="h3">Generating Profiles</Header>

      To profile Python, I prefer <a href="https://github.com/jlfwong/speedscope/wiki/Importing-from-py-spy-(python)">py-spy</a>.  One of the cool things about py-spy is that you can apply it to existing processes.

      You can also use <a href="https://github.com/jlfwong/speedscope/wiki/Importing-from-perf-(linux)">perf</a> to profile Linux executables.
      One gotcha is that you may need to select a non-default thread, using t.

    </Container>
  );
};

export default withLayout(ProfilingPage);
